import statistics

def trimmed_mean(values, trim=0.1):
    # Compute the mean after discarding the lowest and highest fraction of values.
    # trim=0.1 removes 10% from each end.
    if not values:
        raise ValueError('values must not be empty')
    ordered = sorted(values)  # sorting is required before slicing
    k = int(len(ordered) * trim)  # number of items to cut per side
    core = ordered[k:len(ordered) - k] or ordered  # fall back if everything was trimmed
    return statistics.mean(core)

# Split a long list into fixed-size batches, useful for API calls with limits.

def batched(items, size):
    if size <= 0:
        raise ValueError('size must be positive')
    for start in range(0, len(items), size):
        # The final batch may be shorter than 'size'
        yield items[start:start + size]

for batch in batched(list(range(7)), 3):
    print(batch)  # [0, 1, 2], [3, 4, 5], [6]

def flatten(nested):
    # Recursively flatten arbitrarily nested lists into a single flat list.
    flat = []
    for item in nested:
        if isinstance(item, list):
            flat.extend(flatten(item))  # recurse into sublists
        else:
            flat.append(item)  # base case: a plain value
    return flat

# Example: flatten([1, [2, [3, 4]], 5]) returns [1, 2, 3, 4, 5]

// Debounce helper: delays calling fn until the user has stopped typing.
// Prevents excessive API requests from a search box.
function debounce(fn, wait) {
  let timer = null; // holds the pending timeout id
  return function (...args) {
    clearTimeout(timer); // cancel any earlier scheduled call
    timer = setTimeout(() => {
      fn.apply(this, args); // preserve original context and arguments
    }, wait);
  };
}

