/* Reverse a string in place.
   Assumes a null-terminated buffer; does not handle multibyte UTF-8. */
#include <string.h>

void reverse(char *s) {
    size_t i = 0;
    size_t j = strlen(s); /* length excluding the terminator */
    if (j == 0) return;   /* nothing to do for empty strings */
    j--;                  /* index of last character */
    while (i < j) {
        char tmp = s[i];  /* swap the two ends */
        s[i++] = s[j];
        s[j--] = tmp;
    }
}

// Fetch JSON from an endpoint with a simple retry on failure.
// Retries up to 'attempts' times, doubling the delay each time.
async function fetchWithRetry(url, attempts = 3, delay = 500) {
  for (let i = 0; i < attempts; i++) {
    try {
      const res = await fetch(url);
      if (!res.ok) throw new Error(res.status); // treat HTTP errors as failures
      return await res.json();
    } catch (err) {
      if (i === attempts - 1) throw err; // out of retries, rethrow
      await new Promise(r => setTimeout(r, delay));
      delay *= 2; // exponential backoff
    }
  }
}

/* Allocate and initialise a dynamic integer array.
   Caller is responsible for calling free() on the result. */
#include <stdlib.h>

int *make_array(size_t n, int fill) {
    int *arr = malloc(n * sizeof *arr); /* sizeof *arr stays correct if type changes */
    if (arr == NULL) {
        return NULL; /* allocation failed; let the caller decide */
    }
    for (size_t k = 0; k < n; k++) {
        arr[k] = fill; /* set every element to the same value */
    }
    return arr;
}

// Remove duplicate values from an array while keeping the first occurrence.
// A Set stores unique values, so spreading it back gives a clean array.
const unique = (items) => [...new Set(items)];

const readings = [4, 8, 4, 15, 8, 16, 23, 15];
console.log(unique(readings)); // [4, 8, 15, 16, 23]

